package com.ecotrack.backend.advisor;
import com.ecotrack.backend.activity.*; import com.ecotrack.backend.analytics.AnalyticsService; import com.ecotrack.backend.user.UserRepository; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.*;
@Service public class AdvisorService{private final ActivityRepository acts;private final UserRepository users;private final AnalyticsService analytics;public AdvisorService(ActivityRepository a,UserRepository u,AnalyticsService x){acts=a;users=u;analytics=x;}
 public List<Map<String,Object>> recommend(String email){Long uid=users.findByEmailIgnoreCase(email).orElseThrow().getId();LocalDate now=LocalDate.now();List<Object[]> cats=acts.byCategory(uid,now.withDayOfMonth(1),now);List<Map<String,Object>> out=new ArrayList<>();for(Object[] row:cats){String cat=(String)row[0];double value=((Number)row[1]).doubleValue();String title;String reason;if(cat.equals("TRANSPORTATION")){title="Reduce car usage twice a week";reason="Transportation is one of your highest current emission categories.";}else if(cat.equals("ELECTRICITY")){title="Reduce electricity consumption";reason="Improve appliance efficiency and reduce unnecessary electricity use.";}else if(cat.equals("FOOD")){title="Choose lower-impact food more often";reason="Food choices contribute to your footprint; shifting some high-impact choices can help.";}else if(cat.equals("WASTE")){title="Increase reuse and recycling";reason="Reducing waste generation can lower your estimated footprint.";}else{title="Reduce water consumption";reason="Efficient water use can reduce associated energy and emissions.";}out.add(Map.of("category",cat,"title",title,"reason",reason,"currentEmission",value,"estimatedSaving",Math.round(value*.10*10)/10.0,"priority",value>50?"HIGH":"MEDIUM"));}out.sort((a,b)->Double.compare(((Number)b.get("currentEmission")).doubleValue(),((Number)a.get("currentEmission")).doubleValue()));return out;}
 public Map<String,Object> ask(String email,String question){List<Map<String,Object>> r=recommend(email);String answer=r.isEmpty()?"Start recording your activities so I can identify the highest-impact areas.":"Based on your recorded activity, focus first on "+r.get(0).get("category")+". "+r.get(0).get("reason");return Map.of("question",question,"answer",answer,"recommendations",r);}}
